create extension if not exists pgcrypto;
create type public.message_status as enum ('pending','streaming','complete','interrupted','failed');
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,display_name text,avatar_url text,created_at timestamptz not null default now());
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null default 'New chat',model text not null default 'groq:llama-3.3-70b-versatile',system_prompt text,pinned boolean not null default false,archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('user','assistant','system')),content text not null default '',reasoning text,model text,status public.message_status not null default 'pending',tokens_in integer,tokens_out integer,idempotency_key uuid,created_at timestamptz not null default now());
create index if not exists conversations_user_updated_idx on public.conversations(user_id,updated_at desc); create index if not exists messages_conversation_created_idx on public.messages(conversation_id,created_at); create unique index if not exists messages_idempotency_idx on public.messages(user_id,idempotency_key) where idempotency_key is not null;
alter table public.profiles enable row level security; alter table public.conversations enable row level security; alter table public.messages enable row level security;
drop policy if exists profiles_select_own on public.profiles; create policy profiles_select_own on public.profiles for select to authenticated using((select auth.uid())=id);
drop policy if exists profiles_insert_own on public.profiles; create policy profiles_insert_own on public.profiles for insert to authenticated with check((select auth.uid())=id);
drop policy if exists profiles_update_own on public.profiles; create policy profiles_update_own on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
drop policy if exists conversations_select_own on public.conversations; create policy conversations_select_own on public.conversations for select to authenticated using((select auth.uid())=user_id);
drop policy if exists conversations_insert_own on public.conversations; create policy conversations_insert_own on public.conversations for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists conversations_update_own on public.conversations; create policy conversations_update_own on public.conversations for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists conversations_delete_own on public.conversations; create policy conversations_delete_own on public.conversations for delete to authenticated using((select auth.uid())=user_id);
drop policy if exists messages_select_own on public.messages; create policy messages_select_own on public.messages for select to authenticated using((select auth.uid())=user_id);
drop policy if exists messages_insert_own on public.messages; create policy messages_insert_own on public.messages for insert to authenticated with check((select auth.uid())=user_id and exists(select 1 from public.conversations c where c.id=conversation_id and c.user_id=(select auth.uid())));
drop policy if exists messages_update_own on public.messages; create policy messages_update_own on public.messages for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists messages_delete_own on public.messages; create policy messages_delete_own on public.messages for delete to authenticated using((select auth.uid())=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security invoker set search_path=public as $$ begin insert into public.profiles(id,email,display_name,avatar_url) values(new.id,new.email,new.raw_user_meta_data->>'display_name',new.raw_user_meta_data->>'avatar_url') on conflict(id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.touch_conversation() returns trigger language plpgsql security invoker set search_path=public as $$ begin update public.conversations set updated_at=now() where id=new.conversation_id and user_id=new.user_id; return new; end; $$;
drop trigger if exists messages_touch_conversation on public.messages; create trigger messages_touch_conversation after insert or update on public.messages for each row execute function public.touch_conversation();
create or replace function public.interrupt_stale_messages() returns integer language sql security definer set search_path=public as $$ update public.messages set status='interrupted' where status='streaming' and created_at<now()-interval '60 seconds'; select count(*)::integer from public.messages where status='interrupted' and created_at<now()-interval '60 seconds'; $$;
revoke all on function public.interrupt_stale_messages() from public,anon,authenticated;